/**
 * m3-signal-types.ts — M3 进化引擎信号类型枚举和工具函数
 *
 * 使用方：S0（l0.ts）、S1（orchestrator + quality-gate）、
 *         S2（engine-routes）、S3（evolution-loop + circuit-breaker）
 */
/** M3 信号层标识 */
export type SignalLayer = 'S0_dialogue' | 'S1_inference' | 'S2_feedback' | 'S3_runtime';
/** S0 对话质量信号类型 */
export type DialogueSignal = 'user_confusion' | 'user_redirect' | 'user_elaboration' | 'user_confirmation' | 'conversation_depth';
/** S1 推理链信号类型 */
export type InferenceSignal = 'inference_gap' | 'knowledge_gap' | 'quality_degraded' | 'framework_blindspot';
/** S2 用户反馈信号类型 */
export type FeedbackSignal = 'user_modified' | 'user_confirmed' | 'role_deleted' | 'mode_changed';
/** S3 运行协作信号类型（扩展——追加 circuit_breaker_trip） */
/** 所有 M3 信号类型的联合 */
export type M3Signal = {
    layer: 'S0_dialogue';
    type: DialogueSignal;
    sessionId: string;
    data: Record<string, unknown>;
} | {
    layer: 'S1_inference';
    type: InferenceSignal;
    taskRequestId: string;
    data: Record<string, unknown>;
} | {
    layer: 'S2_feedback';
    type: FeedbackSignal;
    blueprintId: string;
    data: Record<string, unknown>;
} | {
    layer: 'S3_runtime';
    type: string;
    gapDimension: string;
    data: Record<string, unknown>;
};
